        { label: 'a(vi)', marks: 1, type: 'short', question: 'Give the symbol of the element that forms an ion with a charge of 1-.', keywords: [['Br','bromine','bromide','I','iodine','iodide']], anyOf: 1 },
        { label: 'b', marks: 2, type: 'short', question: 'Explain why Li, K and Rb have similar chemical properties.', keywords: [['same group','same Group I','all Group I'],['one outer electron','one valence electron','same number of outer electrons','same electronic configuration outer shell'],['same number of electrons in outer shell']], anyOf: 2 }
